// The Kanban: every Tasks row by status. Behind the briefing's 🗂 Kanban button.
//
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md. Plain text only.
// No buttons: the sections that own a card (COMMITMENTS, UPKEEP) carry them.
// Columns are statuses. A card gets in by being a row in Tasks.

const DONE_DAYS = 7;   // how long a finished card stays visible
const PER_COL   = 8;   // longer columns say how many were left out

const input = $('Called').first().json;
const today = String(input.date || $now.toFormat('yyyy-MM-dd')).slice(0, 10);
const since = new Date(Date.parse(today + 'T00:00:00Z') - DONE_DAYS * 864e5).toISOString().slice(0, 10);

const s = (v) => String(v ?? '').trim();
const rows = $('Get Tasks').all().map((i) => i.json).filter((r) => r && s(r.task_id));

// A bill that has not been charged yet is not a card yet.
const live = rows.filter((r) => !s(r.charge_date) || s(r.charge_date).slice(0, 10) <= today);

const card = (r) => {
  const what = s(r.vendor) ? s(r.vendor) + ' · ' + s(r.action) : s(r.action) || s(r.task_id);
  const due  = s(r.due_date) ? ' · due ' + s(r.due_date).slice(0, 10) : '';
  return what + due;
};
const byDue = (a, b) => (s(a.due_date) || '9').localeCompare(s(b.due_date) || '9');

const st = (r) => s(r.status).toLowerCase();
const columns = [
  ['To do', live.filter((r) => !['assigned', 'done', 'wont_fix', 'cancelled'].includes(st(r))).sort(byDue)],
  ['Doing', live.filter((r) => st(r) === 'assigned').sort(byDue)],
  ['Done',  live.filter((r) => st(r) === 'done' && s(r.closed_at).slice(0, 10) >= since)],
];

const blocks = columns
  .filter(([, list]) => list.length)
  .map(([heading, list]) => ({
    heading: heading + ' (' + list.length + ')',
    items: list.slice(0, PER_COL).map(card)
      .concat(list.length > PER_COL ? ['… +' + (list.length - PER_COL) + ' more'] : []),
  }));

// Two callers. The briefing registry passes key 'board' and gets a section.
// The menu button (menu-handler, agent 'board') gets a reply; Send Reply there
// parses Markdown, so the characters that open an entity are replaced.
if (input.key === 'board') {
  // Always one item: silence would look like a crash.
  return [{ json: { key: 'board', icon: '🗂', title: 'BOARD', blocks, empty: 'No cards' } }];
}
const md = (t) => String(t).replace(/[*_`\[]/g, '·');
const response = '🗂 *Kanban*' + (blocks.length
  ? blocks.map((b) => '\n\n*' + md(b.heading) + '*' + b.items.map((i) => '\n  ' + md(i)).join('')).join('')
  : '\n\nNo cards');
return [{ json: { response } }];
